import sys

def count_bits(num):
    count = 0
    while num > 0:
        count += 1
        num &= (num - 1)
    return count

def is_valid(a, b, c, maxm):
    combined = (maxm - 1) & (b | (b << 1) | (b >> 1) | a | c)
    return combined == maxm - 1

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    if n < m:
        n, m = m, n
    maxm = 1 << m

    # Initialize 3D dp array with size (n+1) x maxm x maxm
    dp = [[[100 for _ in range(maxm)] for _ in range(maxm)] for _ in range(n + 1)]
    s = [0] * maxm

    for i in range(maxm):
        s[i] = count_bits(i)
        dp[0][0][i] = 0

    for row in range(1, n + 1):
        for prev_mask in range(maxm):
            for curr_mask in range(maxm):
                for next_mask in range(maxm):
                    if dp[row - 1][prev_mask][next_mask] != 100 and is_valid(prev_mask, next_mask, curr_mask, maxm):
                        dp[row][curr_mask][next_mask] = min(dp[row][curr_mask][next_mask], dp[row - 1][prev_mask][next_mask] + s[next_mask])

    answer = float('inf')
    for i in range(maxm):
        answer = min(dp[n][i][0], answer)

    print(n * m - answer)

if __name__ == "__main__":
    main()

